import React, { useState, useEffect } from 'react';
import api from '../services/api';

const VerInscritos = () => {
  const [ofertas, setOfertas] = useState([]);
  const [inscritos, setInscritos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [ofertaSeleccionada, setOfertaSeleccionada] = useState(null);
  const [mostrarDetalle, setMostrarDetalle] = useState(false);
  const [exportando, setExportando] = useState(false);
  const [fusionando, setFusionando] = useState(false);

  useEffect(() => {
    cargarOfertas();
  }, []);

  const cargarOfertas = async () => {
    try {
      setLoading(true);
      const response = await api.get('/ofertas/mis-ofertas');
      setOfertas(response.data.data || []);
    } catch (error) {
      console.error('Error cargando ofertas:', error);
      setError('Error al cargar las ofertas');
    } finally {
      setLoading(false);
    }
  };

  const cargarInscritos = async (ofertaId) => {
    try {
      setLoading(true);
      const response = await api.get(`/inscripciones/oferta/${ofertaId}`);
      setInscritos(response.data.data || []);
      const oferta = ofertas.find(o => o._id === ofertaId);
      setOfertaSeleccionada(oferta);
      setMostrarDetalle(true);
    } catch (error) {
      console.error('Error cargando inscritos:', error);
      setError('Error al cargar los inscritos');
    } finally {
      setLoading(false);
    }
  };

  const exportarDatosCompletos = async () => {
    if (!ofertaSeleccionada) return;
    try {
      setExportando(true);
      const response = await api.get(`/inscripciones/oferta/${ofertaSeleccionada._id}/exportar/completo`, {
        responseType: 'blob'
      });
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `inscripciones_completas_${ofertaSeleccionada.programa_formacion?.codigo}.xlsx`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      setSuccess('Excel exportado correctamente');
      setTimeout(() => setSuccess(''), 3000);
    } catch (error) {
      console.error('Error exportando:', error);
      setError('Error al exportar los datos');
    } finally {
      setExportando(false);
    }
  };

  const exportarExcelCedulas = async () => {
    if (!ofertaSeleccionada) return;
    try {
      setExportando(true);
      const response = await api.get(`/inscripciones/oferta/${ofertaSeleccionada._id}/exportar/cedulas`, {
        responseType: 'blob'
      });
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `cedulas_${ofertaSeleccionada.programa_formacion?.codigo}.xlsx`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      setSuccess('Excel de cédulas exportado correctamente');
      setTimeout(() => setSuccess(''), 3000);
    } catch (error) {
      console.error('Error exportando Excel de cédulas:', error);
      setError('Error al exportar el Excel de cédulas');
    } finally {
      setExportando(false);
    }
  };

  const fusionarPDFs = async () => {
    if (!ofertaSeleccionada) return;
    try {
      setFusionando(true);
      const response = await api.post(`/inscripciones/oferta/${ofertaSeleccionada._id}/fusionar-pdfs?download=true`, {}, {
        responseType: 'blob'
      });
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `cedulas_fusionadas_${ofertaSeleccionada.programa_formacion?.codigo}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      setSuccess('PDF fusionado descargado correctamente');
      setTimeout(() => setSuccess(''), 3000);
    } catch (error) {
      console.error('Error fusionando PDFs:', error);
      setError('Error al fusionar los PDFs');
    } finally {
      setFusionando(false);
    }
  };

  const volverAlInicio = () => {
    setMostrarDetalle(false);
    setOfertaSeleccionada(null);
    setInscritos([]);
  };

  const obtenerEstadoLink = (oferta) => {
    const disponibles = oferta.cupos_disponibles || 0;
    if (disponibles === 0) return { texto: 'Agotado', clase: 'bg-[#ffdad6] text-[#93000a]' };
    if (disponibles < 5) return { texto: `¡Últimos ${disponibles} cupos!`, clase: 'bg-orange-100 text-orange-700' };
    return { texto: `Disponible (${disponibles} cupos)`, clase: 'bg-[#6cf8bb]/30 text-[#005236]' };
  };

  const totalInscritos = inscritos.length;
  const totalOfertas = ofertas.length;
  const totalInscritosGlobal = ofertas.reduce((sum, o) => sum + (o.cupo_maximo - (o.cupos_disponibles || 0)), 0);
  const disponibilidadMedia = totalOfertas > 0 
    ? Math.round((ofertas.reduce((sum, o) => sum + (o.cupos_disponibles || 0), 0) / ofertas.reduce((sum, o) => sum + (o.cupo_maximo || 0), 0)) * 100)
    : 0;

  if (loading && !mostrarDetalle) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#006c49] mx-auto mb-4"></div>
          <p className="text-[#45474c]">Cargando ofertas...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-full">
      {/* Alerts */}
      {error && (
        <div className="fixed top-20 right-8 z-50 p-4 rounded-xl shadow-lg border flex items-center gap-3 bg-[#ffdad6] border-[#ba1a1a] text-[#93000a] animate-in slide-in-from-right duration-300">
          <span className="material-symbols-outlined">error</span>
          <span className="font-medium">{error}</span>
          <button onClick={() => setError('')} className="ml-auto material-symbols-outlined text-sm opacity-60 hover:opacity-100">close</button>
        </div>
      )}
      {success && (
        <div className="fixed top-20 right-8 z-50 p-4 rounded-xl shadow-lg border flex items-center gap-3 bg-[#6cf8bb]/30 border-[#005236] text-[#005236] animate-in slide-in-from-right duration-300">
          <span className="material-symbols-outlined">check_circle</span>
          <span className="font-medium">{success}</span>
          <button onClick={() => setSuccess('')} className="ml-auto material-symbols-outlined text-sm opacity-60 hover:opacity-100">close</button>
        </div>
      )}

      {/* STATE 1: SUMMARY TABLE */}
      {!mostrarDetalle && (
        <section className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
              <h1 className="text-3xl md:text-4xl font-semibold text-[#091426] mb-1">Inscritos</h1>
            </div>
          </div>

          {/* Bento Summary Grid */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-[#c5c6cd] flex justify-between items-center">
              <div>
                <p className="text-[#45474c] text-xs uppercase mb-1">Total Ofertas</p>
                <p className="text-4xl md:text-5xl font-bold text-[#091426]">{totalOfertas}</p>
              </div>
              <div className="w-12 h-12 bg-[#dce9ff] rounded-full flex items-center justify-center">
                <span className="material-symbols-outlined text-[#006c49]">list_alt</span>
              </div>
            </div>
            <div className="bg-white p-6 rounded-xl shadow-sm border border-[#c5c6cd] flex justify-between items-center">
              <div>
                <p className="text-[#45474c] text-xs uppercase mb-1">Inscritos Totales</p>
                <p className="text-4xl md:text-5xl font-bold text-[#006c49]">{totalInscritosGlobal}</p>
              </div>
              <div className="w-12 h-12 bg-[#6cf8bb]/30 rounded-full flex items-center justify-center">
                <span className="material-symbols-outlined text-[#005236]">group</span>
              </div>
            </div>
            <div className="bg-white p-6 rounded-xl shadow-sm border border-[#c5c6cd] flex justify-between items-center">
              <div>
                <p className="text-[#45474c] text-xs uppercase mb-1">Disponibilidad Media</p>
                <p className="text-4xl md:text-5xl font-bold text-[#001334]">{disponibilidadMedia}%</p>
              </div>
              <div className="w-12 h-12 bg-[#d8e2ff] rounded-full flex items-center justify-center">
                <span className="material-symbols-outlined text-[#001334]">pie_chart</span>
              </div>
            </div>
          </div>

          {/* Ofertas Table */}
          <div className="bg-white rounded-xl shadow-sm border border-[#c5c6cd] overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-[#eff4ff] border-b border-[#c5c6cd]">
                  <tr>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Programa</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Código</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Cupo Total</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Inscritos</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Disponibles</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Estado del Link</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Acción</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#dce9ff]">
                  {ofertas.map((oferta) => {
                    const inscritosCount = oferta.cupo_maximo - (oferta.cupos_disponibles || 0);
                    const estado = obtenerEstadoLink(oferta);
                    return (
                      <tr key={oferta._id} className="hover:bg-[#f8f9ff] transition-colors group">
                        <td className="px-6 py-4 font-medium text-[#091426]">{oferta.programa_formacion?.nombre_programa || 'N/A'}</td>
                        <td className="px-6 py-4 text-sm text-[#45474c]">{oferta.programa_formacion?.codigo || 'N/A'}</td>
                        <td className="px-6 py-4">{oferta.cupo_maximo}</td>
                        <td className="px-6 py-4">{inscritosCount}</td>
                        <td className="px-6 py-4">{oferta.cupos_disponibles}</td>
                        <td className="px-6 py-4">
                          <span className={`inline-flex items-center px-2 py-1 rounded text-xs font-bold uppercase ${estado.clase}`}>
                            {estado.texto}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          <button 
                            onClick={() => cargarInscritos(oferta._id)}
                            className="text-[#006c49] font-bold flex items-center gap-1 hover:underline transition-all"
                          >
                            Ver inscritos <span className="material-symbols-outlined text-sm">visibility</span>
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>

          {ofertas.length === 0 && (
            <div className="text-center py-12 bg-white rounded-xl border border-[#c5c6cd]">
              <p className="text-[#45474c]">No tienes ofertas creadas aún.</p>
            </div>
          )}
        </section>
      )}

      {/* STATE 2: DETAIL VIEW */}
      {mostrarDetalle && ofertaSeleccionada && (
        <section className="animate-in fade-in slide-in-from-right-4 duration-500">
          <div className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <button 
                onClick={volverAlInicio}
                className="w-10 h-10 rounded-full border border-[#c5c6cd] flex items-center justify-center hover:bg-[#eff4ff] transition-all active:scale-90"
              >
                <span className="material-symbols-outlined">arrow_back</span>
              </button>
              <div>
                <h1 className="text-3xl md:text-4xl font-semibold text-[#091426]">Lista de Inscritos</h1>
                <p className="text-[#45474c]">Detalle minucioso de aspirantes registrados para la oferta seleccionada.</p>
              </div>
            </div>
            <div className="flex flex-wrap gap-2">
              <button 
                onClick={exportarDatosCompletos}
                disabled={exportando || inscritos.length === 0}
                className={`bg-[#006c49] text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold shadow-sm hover:brightness-110 active:scale-95 transition-all text-sm ${(exportando || inscritos.length === 0) ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <span className="material-symbols-outlined text-base">download</span>
                Exportar Datos Completos
              </button>
              <button 
                onClick={exportarExcelCedulas}
                disabled={exportando || inscritos.length === 0}
                className={`bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold shadow-sm hover:brightness-110 active:scale-95 transition-all text-sm ${(exportando || inscritos.length === 0) ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <span className="material-symbols-outlined text-base">table_view</span>
                Exportar Excel-Cedulas
              </button>
              <button 
                onClick={fusionarPDFs}
                disabled={fusionando || inscritos.length === 0}
                className={`bg-purple-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold shadow-sm hover:brightness-110 active:scale-95 transition-all text-sm ${(fusionando || inscritos.length === 0) ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <span className="material-symbols-outlined text-base">picture_as_pdf</span>
                {fusionando ? 'Fusionando...' : 'Fusionar PDFs'}
              </button>
              <button 
                onClick={volverAlInicio}
                className="bg-red-500 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold shadow-sm hover:brightness-110 active:scale-95 transition-all text-sm"
              >
                <span className="material-symbols-outlined text-base">delete</span>
                Limpiar
              </button>
            </div>
          </div>

          {/* Selected Offer Info Card */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-[#c5c6cd] mb-8 flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-4">
              <div className="w-16 h-16 bg-[#6cf8bb]/30 rounded-xl flex items-center justify-center">
                <span className="material-symbols-outlined text-3xl text-[#005236]">assignment_ind</span>
              </div>
              <div>
                <h2 className="text-2xl font-semibold text-[#091426] leading-tight">{ofertaSeleccionada.programa_formacion?.nombre_programa}</h2>
                <div className="flex gap-4 mt-2">
                  <span className="flex items-center gap-1 text-[#45474c] text-sm">
                    <span className="material-symbols-outlined text-sm">tag</span>
                    {ofertaSeleccionada.programa_formacion?.codigo}
                  </span>
                  <span className="flex items-center gap-1 text-[#006c49] font-bold text-sm">
                    <span className="material-symbols-outlined text-sm">group</span>
                    {inscritos.length} inscritos registrados
                  </span>
                </div>
              </div>
            </div>
            <button 
              onClick={volverAlInicio}
              className="border-2 border-[#006c49] text-[#006c49] font-bold px-6 py-2 rounded-lg hover:bg-[#006c49]/5 transition-all active:scale-95"
            >
              Volver al Inicio
            </button>
          </div>

          {/* Inscritos Table */}
          <div className="bg-white rounded-xl shadow-sm border border-[#c5c6cd] overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-[#eff4ff] border-b border-[#c5c6cd]">
                  <tr>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Nombre Completo</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Tipo Documento</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Documento</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Email</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Teléfono</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Caracterización</th>
                    <th className="px-6 py-3 text-xs text-[#45474c] uppercase tracking-wider">Oferta</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#dce9ff]">
                  {inscritos.map((inscrito) => (
                    <tr key={inscrito._id} className="hover:bg-[#f8f9ff] transition-colors">
                      <td className="px-6 py-4 font-medium text-[#091426]">{inscrito.nombres} {inscrito.apellidos}</td>
                      <td className="px-6 py-4">{inscrito.tipo_documento?.nombre || 'N/A'}</td>
                      <td className="px-6 py-4 text-sm font-mono">{inscrito.numero_documento}</td>
                      <td className="px-6 py-4 text-[#45474c]">{inscrito.correo}</td>
                      <td className="px-6 py-4">{inscrito.telefono}</td>
                      <td className="px-6 py-4">
                        <span className="px-2 py-1 bg-[#dce9ff] rounded text-xs">{inscrito.caracterizacion?.tipo_caracterizacion || 'N/A'}</span>
                      </td>
                      <td className="px-6 py-4 text-sm">{ofertaSeleccionada.programa_formacion?.codigo}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div className="px-6 py-4 bg-[#eff4ff] border-t border-[#c5c6cd] flex justify-between items-center">
              <p className="font-bold text-[#091426]">Total de inscritos: <span className="bg-[#006c49] text-white px-2 py-0.5 rounded ml-1">{inscritos.length}</span></p>
            </div>
          </div>

          {inscritos.length === 0 && (
            <div className="text-center py-12 bg-white rounded-xl border border-[#c5c6cd]">
              <p className="text-[#45474c]">No hay inscritos para esta oferta aún.</p>
            </div>
          )}
        </section>
      )}
    </div>
  );
};

export default VerInscritos;
